app.get('/api/platform-invoices', async (req, res) => {
  const month = String(req.query.month || '');
  const all = !month || month === 'all';
  if (!all && !/^\d{4}-\d{2}$/.test(month)) return res.status(400).json({ error: 'month=YYYY-MM required' });
  try { await piRefileAirbnbByIssueDate(); } catch (eRefile) {}
  if (pool) {
    try {
      await ensurePlatInvTable();
      const r = all
        ? await pool.query(
            `SELECT id, month, channel, scope, partner, filename, mime, size, source, uploaded_by, created_at, meta
             FROM platform_invoices ORDER BY partner, channel, month, filename, id`)
        : await pool.query(
            `SELECT id, month, channel, scope, partner, filename, mime, size, source, uploaded_by, created_at, meta
             FROM platform_invoices WHERE month=$1 ORDER BY channel, partner, filename, id`, [month]);
      return res.json({ ok: true, month: all ? 'all' : month, items: r.rows.map(platInvMeta) });
    } catch (e) { return res.status(500).json({ error: e.message }); }
  }
  const items = [..._memPlatInv.values()].filter(x => all || x.month === month).map(platInvMeta);
  res.json({ ok: true, month: all ? 'all' : month, items, db: false });
});
